"use strict";

// Auri's voice. Three engines, all free and local:
//  - "browser": the OS text-to-speech (instant, flat).
//  - "piper":   Piper neural voices, generated by the A.U.R.A server on this PC (very fast).
//  - "kokoro":  Kokoro-82M neural voices, generated by the A.U.R.A server (the most expressive).
// The neural voices are opt-in packs downloaded from Settings > AURI Character > Voice (/api/voice/*); until a pack
// is there she uses the browser voice. Kokoro and Piper have no emotion switch, so emotion is built around them:
// voice and speed per mood, WebAudio effects (pitch, low-pass, drive, echo, vibrato) and punctuation shaping.
// Sync with the bubbles: she finishes the sentence she is saying, then says the LATEST bubble (older pending lines
// are dropped), and the bubble stays up until she has finished it ("aura:speech" event).
(function initAvatarVoice() {
  const KEY = "aura.speech";
  const synth = window.speechSynthesis;
  const defaults = { on: false, engine: "browser", voice: "auto", volume: 0.85 };
  let cfg = { ...defaults };
  try { cfg = { ...defaults, ...JSON.parse(localStorage.getItem(KEY) || "{}") }; } catch { /* first run */ }
  delete cfg.model; // the in-browser Kokoro model is gone (it was too slow on CPU)
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(cfg)); } catch { /* storage unavailable */ } };
  const level = () => Number(document.documentElement.dataset.avatarVoice ?? 2);
  const listeners = new Set();
  const emit = () => listeners.forEach((fn) => fn(info()));

  // ── emotions ── speed = model speed, rate = playback rate (pitch + tempo), lp = low-pass Hz, drive = distortion,
  // echo = tail, vib = vibrato cents. voice = Kokoro voice. Female voices only: Auri is a she.
  const EMOTIONS = {
    neutral: { voice: "af_heart", speed: 1.0, rate: 1.0, gain: 1 },
    happy: { voice: "af_bella", speed: 1.08, rate: 1.06, gain: 1.05 },
    hyped: { voice: "af_bella", speed: 1.22, rate: 1.1, gain: 1.15, vib: 14 },
    adrenaline: { voice: "af_nicole", speed: 1.32, rate: 1.12, gain: 1.2, drive: 0.15 },
    bored: { voice: "af_nicole", speed: 0.8, rate: 0.93, gain: 0.85, lp: 2600 },
    sulk: { voice: "af_sky", speed: 0.85, rate: 0.9, gain: 0.9, lp: 3200 },
    angry: { voice: "af_bella", speed: 1.15, rate: 0.9, gain: 1.2, drive: 0.45 },
    rage: { voice: "af_nicole", speed: 1.18, rate: 0.8, gain: 1.35, drive: 0.85, echo: 0.2 },
    creepy: { voice: "af_nicole", speed: 0.88, rate: 0.82, gain: 1, echo: 0.3, lp: 4200 },
    sing: { voice: "af_heart", speed: 0.92, rate: 1.1, gain: 1.05, vib: 45, echo: 0.15 },
    shout: { voice: "af_bella", speed: 1.0, rate: 1.05, gain: 1.5, drive: 0.35, echo: 0.45 } // anime battle cry
  };

  function inferEmotion(text, opts) {
    if (opts.emotion) return opts.emotion;
    if (opts.loud) return "rage";
    const t = String(text);
    const letters = t.replace(/[^A-Za-z]/g, "");
    const shouting = letters.length > 6 && letters === letters.toUpperCase();
    if (/[♪♫♬]/.test(t)) return "sing";
    if (shouting && /!/.test(t)) return level() >= 4 ? "rage" : "angry";
    if (/#@|[#@%&*$]{2}|ow!|ouch|hands off|poke/i.test(t)) return "angry";
    if (/\.\.\.|yawn|zzz|boring|nothing|glacier|sleep/i.test(t) && !/!/.test(t)) return "bored";
    if (/sorry|okay\.|fine\.|lost my temper|i'm back|regret/i.test(t)) return "sulk";
    if (/yatta|sugoi|banzai|kita|jackpot|found it|adrenaline|power level|nailed|yes yes|got you/i.test(t)) return "hyped";
    if (/!/.test(t)) return level() >= 3 ? "hyped" : "happy";
    return level() >= 4 ? "creepy" : "neutral";
  }
  function clean(text) {
    return String(text || "")
      .replace(/[♪♫♬♩]/g, "")
      .replace(/(?:[#@%&*$]\w?){3,}|[#@%&*$!?]{3,}/g, " beep ")
      .replace(/\b\w*[#@%&*$]\w*[#@%&*$]\w*\b/g, " beep ")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 260);
  }
  function shape(text, emo) {
    let t = clean(String(text).split("\n").join(". "));
    if (emo === "bored") t = "Meh... " + t.replace(/[.!]+$/, "") + "...";
    if (emo === "sulk") t = t.replace(/^\.+\s*/, "");
    if (emo === "rage" || emo === "angry" || emo === "shout") t = t.replace(/\b([A-Z]{3,})\b/g, (w) => w[0] + w.slice(1).toLowerCase());
    if (emo === "rage" || emo === "angry") t = t.replace(/!+/g, "!!");
    return t;
  }

  // ── server packs ── status comes from /api/voice/status; it is polled only while a download runs.
  let server = null, serverError = "", pollTimer = null;
  const installed = (id) => Boolean(server && server.packs.some((p) => p.id === id && p.installed));
  const piperPacks = () => (server ? server.packs.filter((p) => p.engine === "piper") : []);
  const kokoroVoices = () => (server ? server.kokoroVoices : ["af_heart", "af_bella", "af_nicole", "af_sky", "af_sarah", "bf_emma", "bf_isabella"]);
  // The pack that speaks now: null means "browser voice" (engine not chosen, or its pack not downloaded yet).
  function activePack() {
    if (cfg.engine === "kokoro") return installed("kokoro") ? "kokoro" : null;
    if (cfg.engine === "piper") return cfg.voice !== "auto" && installed(cfg.voice) ? cfg.voice : (piperPacks().find((p) => p.installed) || {}).id || null;
    return null;
  }
  const pickVoice = (emo) => (cfg.engine === "kokoro" && cfg.voice !== "auto" && kokoroVoices().includes(cfg.voice) ? cfg.voice : (EMOTIONS[emo] || EMOTIONS.neutral).voice);

  async function refresh() {
    try {
      const res = await fetch("/api/voice/status", { cache: "no-store" });
      if (!res.ok) throw new Error(`status ${res.status}`);
      const before = server && server.job;
      server = await res.json();
      serverError = "";
      const job = server.job;
      // a download that just finished switches her to that voice
      if (job && job.done && !job.error && before && !before.done) { cfg.engine = server.packs.find((p) => p.id === job.pack).engine; cfg.voice = cfg.engine === "piper" ? job.pack : "auto"; save(); warm(); }
    } catch (err) { serverError = err.message; }
    clearTimeout(pollTimer);
    if (server && server.job && !server.job.done) pollTimer = setTimeout(refresh, 900);
    emit();
  }
  async function post(path, body) {
    const res = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
    return data;
  }
  async function download(pack) {
    try { server = await post("/api/voice/install", { pack }); serverError = ""; } catch (err) { serverError = err.message; }
    refresh();
  }
  async function remove(pack) {
    stop();
    try { server = await post("/api/voice/remove", { pack }); serverError = ""; } catch (err) { serverError = err.message; }
    cache.clear();
    if (!activePack()) { cfg.voice = "auto"; save(); }
    refresh();
  }

  // ── generation ──
  let lastGen = null, rtf = null, generating = 0; // rtf = generation time / speech time (moving average)
  const cache = new Map();
  const cacheKey = (pack, text, emoName, lang = "") => { const emo = EMOTIONS[emoName] || EMOTIONS.neutral; return `${pack}|${lang}|${pickVoice(emoName)}|${emo.speed}|${shape(text, emoName)}`; };
  // lang "ja": the line is Japanese romaji (battle cries) and is said with Japanese sounds by the server voices.
  async function generate(text, emoName, low = false, lang = "") {
    const pack = activePack();
    const emo = EMOTIONS[emoName] || EMOTIONS.neutral;
    const line = shape(text, emoName);
    if (!pack || !line) return null;
    const key = cacheKey(pack, text, emoName, lang);
    if (cache.has(key)) return { ...cache.get(key), emo };
    generating += 1; emit();
    try {
      const res = await fetch("/api/voice/speak", {
        method: "POST", headers: { "Content-Type": "application/json" }, signal: AbortSignal.timeout(30000),
        body: JSON.stringify({ pack, voice: pickVoice(emoName), speed: emo.speed, text: line, lang, low })
      });
      if (res.status === 204) return null; // skipped: a newer line took its place
      if (!res.ok) { const e = await res.json().catch(() => ({})); serverError = e.error || `HTTP ${res.status}`; refresh(); return null; }
      const audio = { data: new Float32Array(await res.arrayBuffer()), rate: Number(res.headers.get("X-Sample-Rate")) || 24000 };
      const ms = Number(res.headers.get("X-Gen-Ms")) || 0, seconds = audio.data.length / audio.rate;
      lastGen = { ms, seconds: Math.round(seconds * 10) / 10, emotion: emoName, pack };
      const r = ms / Math.max(200, seconds * 1000);
      rtf = rtf == null ? r : rtf * 0.6 + r * 0.4;
      serverError = "";
      cache.set(key, audio);
      if (cache.size > 80) cache.delete(cache.keys().next().value);
      return { ...audio, emo };
    } catch (err) {
      serverError = err.name === "TimeoutError" ? "the voice engine took too long" : err.message;
      return null;
    } finally { generating -= 1; emit(); }
  }
  // The first line loads the model (a few seconds): do it while she is quiet.
  const warm = () => { if (cfg.on && activePack()) generate("Hi.", "neutral", true); };

  // ── playback ──
  let ctx = null, current = null;
  function stopCurrent() { if (current) { try { current.stop(); } catch { /* already stopped */ } current = null; } }
  function curve(amount) {
    const n = 256, c = new Float32Array(n), k = amount * 60;
    for (let i = 0; i < n; i += 1) { const x = (i / (n - 1)) * 2 - 1; c[i] = ((1 + k) * x) / (1 + k * Math.abs(x)); }
    return c;
  }
  function play(audio, emo, volume, onStart) {
    return new Promise((resolve) => {
      ctx = ctx || new (window.AudioContext || window.webkitAudioContext)();
      if (ctx.state === "suspended") ctx.resume();
      stopCurrent();
      const buf = ctx.createBuffer(1, audio.data.length, audio.rate);
      buf.copyToChannel(audio.data, 0);
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.playbackRate.value = emo.rate || 1;
      let node = src, lfo = null;
      if (emo.vib) { lfo = ctx.createOscillator(); const depth = ctx.createGain(); lfo.frequency.value = 6; depth.gain.value = emo.vib; lfo.connect(depth); depth.connect(src.detune); lfo.start(); }
      if (emo.lp) { const f = ctx.createBiquadFilter(); f.type = "lowpass"; f.frequency.value = emo.lp; node.connect(f); node = f; }
      if (emo.drive) { const s = ctx.createWaveShaper(); s.curve = curve(emo.drive); s.oversample = "2x"; node.connect(s); node = s; }
      const gain = ctx.createGain();
      gain.gain.value = Math.min(1.6, volume * (emo.gain || 1));
      node.connect(gain); gain.connect(ctx.destination);
      if (emo.echo) { const d = ctx.createDelay(1), fb = ctx.createGain(), wet = ctx.createGain(); d.delayTime.value = 0.17; fb.gain.value = 0.38; wet.gain.value = emo.echo * 2; gain.connect(d); d.connect(fb); fb.connect(d); d.connect(wet); wet.connect(ctx.destination); }
      const seconds = audio.data.length / audio.rate / (emo.rate || 1);
      let done = false;
      const finish = () => { if (done) return; done = true; if (lfo) try { lfo.stop(); } catch { /* stopped */ } if (current === src) current = null; resolve(); };
      src.onended = finish;
      current = src;
      src.start();
      onStart(seconds * 1000);
      setTimeout(finish, seconds * 1000 + 1200);
    });
  }
  function speakBrowser(item, onStart) {
    return new Promise((resolve) => {
      if (!synth || !synth.getVoices().length) return resolve(); // no speech engine at all
      const line = clean(String(item.text).split("\n").join(". "));
      if (!line) return resolve();
      const u = new SpeechSynthesisUtterance(line);
      const list = synth.getVoices();
      const v = list.find((x) => x.voiceURI === cfg.voice) || list.find((x) => /^en/i.test(x.lang) && /female|zira|aria|jenny|samantha|hazel|susan/i.test(x.name)) || list.find((x) => /^en/i.test(x.lang));
      if (v) { u.voice = v; u.lang = v.lang; }
      u.volume = Math.min(1, cfg.volume * (item.opts.loud ? 1.25 : 1));
      u.pitch = { rage: 0.5, angry: 0.7, creepy: 0.6, bored: 0.85, hyped: 1.4, adrenaline: 1.5, happy: 1.25, shout: 1.2 }[item.emoName] ?? 1.1;
      u.rate = { rage: 1.2, angry: 1.1, creepy: 0.85, bored: 0.8, hyped: 1.25, adrenaline: 1.35, sulk: 0.85 }[item.emoName] ?? 1;
      let done = false;
      const finish = () => { if (!done) { done = true; resolve(); } };
      let started = false;
      u.onstart = () => { started = true; onStart(line.split(/\s+/).length * 380 + 600); };
      u.onend = u.onerror = finish;
      synth.speak(u);
      setTimeout(() => { if (!started) finish(); }, 2500); // no speech engine answered: never block the queue
      setTimeout(finish, 20000);
    });
  }

  // ── queue: one line playing, at most one (the newest) waiting ──
  let currentItem = null, pending = null, played = 0;
  async function pump() {
    if (currentItem || !pending) return;
    const item = pending;
    pending = null;
    currentItem = item;
    let started = false, dropped = false;
    // the bubble learns how long it has to stay up for this line
    const onStart = (ms) => { started = true; played += 1; window.dispatchEvent(new CustomEvent("aura:speech", { detail: { text: item.text, ms } })); };
    try {
      // When the neural voice is known to be too slow, do not keep the bubble waiting: unless the audio is (almost) ready, use the browser voice.
      const wait = tooSlow() && !item.opts.force ? Promise.race([item.ready, new Promise((r) => setTimeout(() => r(null), 400))]) : item.ready;
      const audio = item.ready ? await wait : null;
      if (item.cancelled) return;
      // A newer bubble arrived while this one was being prepared: saying the old one now would be out of sync.
      if (pending && !item.opts.force && !item.opts.loud) { dropped = true; return; }
      if (audio) await play(audio, audio.emo, cfg.volume * (item.opts.loud ? 1.2 : 1), onStart);
      else await speakBrowser(item, onStart);
    } finally {
      // no voice came out (no speech engine, an error): her bubble still shows the line
      if (!started && !dropped && !item.cancelled) window.dispatchEvent(new CustomEvent("aura:speech", { detail: { text: item.text, ms: Math.max(1500, estimate(item.text)) } }));
      currentItem = null;
      pump();
    }
  }

  let hinted = null;
  const hint = (emotion) => { hinted = { emotion, t: Date.now() }; };
  const estimate = (text) => (cfg.on ? Math.round(String(text).split(/\s+/).length * 380 + 700) : 0);
  const tooSlow = () => rtf != null && rtf > 1.3;

  function speak(text, opts = {}) {
    if (!cfg.on || document.hidden || demo) return; // during the mood demo her bubbles stay silent
    if (hinted && Date.now() - hinted.t < 1500 && !opts.emotion) opts = { ...opts, emotion: hinted.emotion };
    hinted = null;
    const item = { text, opts, emoName: inferEmotion(text, opts), cancelled: false };
    if (opts.loud || opts.interrupt || item.emoName === "rage") { if (currentItem) currentItem.cancelled = true; stopCurrent(); if (synth) synth.cancel(); }
    if (pending) pending.cancelled = true; // only the latest bubble is worth saying
    const pack = activePack();
    item.ready = pack && (!tooSlow() || opts.force || cache.has(cacheKey(pack, text, item.emoName, opts.lang))) ? generate(text, item.emoName, false, opts.lang) : null;
    pending = item;
    pump();
    return true; // she will say it: the caller's bubble waits for the "aura:speech" event
  }
  function stop() { demo = null; if (pending) pending.cancelled = true; pending = null; if (currentItem) currentItem.cancelled = true; stopCurrent(); if (synth) synth.cancel(); emit(); }

  // The Test button: a short monologue through her moods, played back to back (nothing is dropped). The next line
  // is generated while the current one plays; each line also shows in her bubble.
  const DEMO = [
    ["Hi, I'm AURI. Want to hear all my moods? Here we go.", "neutral"],
    ["Ooh, a brand new target! This is going to be fun.", "happy"],
    ["YATTA! Forty subdomains in one go! I love my job!", "hyped"],
    ["Wait. Is that... a vulnerability? My heart is racing!", "adrenaline"],
    ["...zero results. Again. I'm so bored I could sleep.", "bored"],
    ["HEY! Stop poking me! I said STOP!", "rage"],
    ["I see every open port. And I always see you.", "creepy"],
    ["♪ Scanning all night, finding bugs till the light ♪", "sing"],
    ["KAMEHAMEHAAAA!!", "shout"],
    ["Okay, okay. I'm done. So... do you like my voice?", "sulk"]
  ];
  let demo = null;
  async function showcase(lines = DEMO) {
    stop();
    if (!cfg.on) return;
    const token = {};
    demo = token;
    emit();
    const prepare = ([text, emotion]) => (activePack() ? generate(text, emotion) : Promise.resolve(null));
    let next = prepare(lines[0]);
    try {
      for (let i = 0; i < lines.length && demo === token; i += 1) {
        const [text, emotion] = lines[i];
        const audio = await next;
        next = i + 1 < lines.length ? prepare(lines[i + 1]) : null;
        if (demo !== token) return;
        const onStart = (ms) => { played += 1; if (window.AuraAvatar) window.AuraAvatar.say(text, ms + 400, true); };
        if (audio) await play(audio, audio.emo, cfg.volume, onStart);
        else await speakBrowser({ text, opts: {}, emoName: emotion }, onStart);
        await new Promise((r) => setTimeout(r, 250));
      }
    } finally { if (demo === token) { demo = null; emit(); } }
  }

  // Lines that must land on time (battle cries) are generated ahead, only while she is silent.
  const prefetchList = [];
  function prefetch(lines) {
    prefetchList.push(...lines);
    const tick = async () => {
      if (!prefetchList.length) return;
      if (!cfg.on || !activePack() || currentItem || pending || generating) { setTimeout(tick, 2500); return; }
      const [text, emotion, lang] = prefetchList.shift();
      await generate(text, emotion, true, lang);
      setTimeout(tick, 400);
    };
    setTimeout(tick, 3000);
  }

  const info = () => ({ cfg: { ...cfg }, server, serverError, pack: activePack(), lastGen, played, rtf, generating, slow: tooSlow(), demo: Boolean(demo), kokoroVoices: kokoroVoices(), piperPacks: piperPacks() });
  function set(patch) {
    cfg = { ...cfg, ...patch };
    save();
    if (patch.on === false || patch.engine) stop();
    if (patch.on || patch.engine || patch.voice) warm();
    emit();
  }

  // One-time cleanup of the old in-browser Kokoro model (~92 MB in the browser cache).
  if (window.caches && !localStorage.getItem("aura.speech.cleaned")) {
    caches.delete("transformers-cache").catch(() => {}).finally(() => { caches.delete("kokoro-voices").catch(() => {}); });
    try { localStorage.setItem("aura.speech.cleaned", "1"); } catch { /* storage unavailable */ }
  }
  refresh().then(() => setTimeout(warm, 2500));
  window.AuraSpeech = {
    speak, stop, showcase, hint, estimate, prefetch, set, download, remove, refresh, info,
    onChange: (fn) => { listeners.add(fn); return () => listeners.delete(fn); },
    state: info, isOn: () => cfg.on, inDemo: () => Boolean(demo), emotions: Object.keys(EMOTIONS)
  };
})();
